source_texts.score_band_repo:
from scores import score_band

pass_mark = int(input())
excellence_mark = int(input())
count = int(input())
counts = {"excellent": 0, "pass": 0, "retry": 0}
for _ in range(count):
    user, score = input().split("|")
    band = score_band(int(score), pass_mark, excellence_mark)
    counts[band] += 1
    print(f"{user}:{band}")
print(
    f"excellent={counts['excellent']},pass={counts['pass']},"
    f"retry={counts['retry']}"
)

def score_band(score: int, pass_mark: int, excellence_mark: int) -> str:
    if score >= excellence_mark:
        return "excellent"
    if score >= pass_mark:
        return "pass"
    return "retry"

source_texts.ledger_reconciliation_repo:
def absolute_difference(expected: int, actual: int) -> int:
    return abs(expected - actual)


def is_within_tolerance(difference: int, tolerance: int) -> bool:
    return difference <= tolerance

from ledger import absolute_difference, is_within_tolerance

tolerance = int(input())
count = int(input())
matched = 0
variance = 0
for _ in range(count):
    entry_id, expected, actual = input().split("|")
    difference = absolute_difference(int(expected), int(actual))
    variance += difference
    if is_within_tolerance(difference, tolerance):
        matched += 1
        print(f"{entry_id}:match")
    else:
        print(f"{entry_id}:diff={difference}")
print(f"matched={matched},unmatched={count - matched},variance={variance}")

