source_texts.tag_dedup_repo:
mod tags;

use tags::normalize_tag;
use std::collections::HashSet;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut seen = HashSet::new();
    let mut duplicates = 0;
    for _ in 0..count {
        let tag = normalize_tag(lines.next().unwrap_or(""));
        if seen.insert(tag.clone()) {
            println!("{tag}");
        } else {
            duplicates += 1;
        }
    }
    println!("unique={},duplicates={duplicates}", seen.len());
}

pub fn normalize_tag(tag: &str) -> String {
    tag.to_lowercase()
}

source_texts.filtered_report_repo:
mod report_rules;

use report_rules::{format_entry, should_include};
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let min_length: usize = lines.next().unwrap_or("0").parse().unwrap();
    let entries: Vec<&str> = (0..count).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for (offset, entry) in entries.iter().enumerate() {
        if should_include(entry, min_length) {
            contents.push_str(&format_entry(offset + 1, entry));
            contents.push('\n');
            saved += 1;
            characters += entry.chars().count();
        }
    }
    fs::write("filtered_report.txt", contents).unwrap();
    println!("saved={saved}|skipped={}|characters={characters}", count - saved);
}

pub fn should_include(entry: &str, min_length: usize) -> bool {
    entry.chars().count() >= min_length
}

pub fn format_entry(index: usize, entry: &str) -> String {
    format!("{index}|{entry}")
}

source_texts.timesheet_pay_repo:
mod payroll;

use payroll::calculate_pay;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut total = 0;
    for _ in 0..count {
        let mut parts = lines.next().unwrap_or("").split('|');
        let employee = parts.next().unwrap();
        let hours: i64 = parts.next().unwrap().parse().unwrap();
        let rate: i64 = parts.next().unwrap().parse().unwrap();
        let pay = calculate_pay(hours, rate);
        println!("{employee}:pay={pay}");
        total += pay;
    }
    println!("total={total}");
}

pub fn calculate_pay(hours: i64, rate: i64) -> i64 {
    let regular_hours = hours.min(40);
    let overtime_hours = (hours - 40).max(0);
    regular_hours * rate + overtime_hours * rate * 2
}

