use sensor::sensor_band;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let low: i64 = lines.next().unwrap().parse().unwrap();
    let high: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut low_count, mut normal_count, mut high_count) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let reading: i64 = parts.next().unwrap().parse().unwrap();
        let band = sensor_band(reading, low, high);
        println!("{id}:{band}");
        match band {
            "low" => low_count += 1,
            "high" => high_count += 1,
            _ => normal_count += 1,
        }
    }
    println!("low={low_count},normal={normal_count},high={high_count}");
}

pub fn sensor_band(reading: i64, low: i64, high: i64) -> &'static str {
    if reading < low {
        "low"
    } else if reading > high {
        "high"
    } else {
        "normal"
    }
}

