source_texts.incident_routing_repo:
from routing import channel_for

count = int(input())
counts = {"email": 0, "chat": 0, "pager": 0}
for _ in range(count):
    team, severity, after_hours = input().split("|")
    channel = channel_for(severity, after_hours)
    counts[channel] += 1
    print(f"{team}:{channel}")
print(f"email={counts['email']},chat={counts['chat']},pager={counts['pager']}")

def channel_for(severity: str, after_hours: str) -> str:
    if severity == "low":
        return "email"
    if severity == "high" and after_hours == "no":
        return "chat"
    return "pager"

source_texts.score_band_repo:
from scores import score_band

pass_mark = int(input())
excellence_mark = int(input())
count = int(input())
counts = {"excellent": 0, "pass": 0, "retry": 0}
for _ in range(count):
    user, score = input().split("|")
    band = score_band(int(score), pass_mark, excellence_mark)
    counts[band] += 1
    print(f"{user}:{band}")
print(
    f"excellent={counts['excellent']},pass={counts['pass']},retry={counts['retry']}"
)

def score_band(score: int, pass_mark: int, excellence_mark: int) -> str:
    if score >= excellence_mark:
        return "excellent"
    if score >= pass_mark:
        return "pass"
    return "retry"

