pub fn due_minutes(priority: &str, tier: &str, after_hours: &str) -> u64 {
    let base: u64 = match priority {
        "high" => 120,
        "critical" => 30,
        _ => 480,
    };
    let adjusted = if tier == "premium" {
        base.saturating_sub(30).max(15)
    } else {
        base
    };
    adjusted + if after_hours == "yes" { 60 } else { 0 }
}

