mod sensor;

use sensor::sensor_band;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let low_threshold: i64 = lines.next().unwrap().parse().unwrap();
    let high_threshold: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut low, mut normal, mut high) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let sensor = parts.next().unwrap();
        let reading: i64 = parts.next().unwrap().parse().unwrap();
        let band = sensor_band(reading, low_threshold, high_threshold);
        match band {
            "low" => low += 1,
            "normal" => normal += 1,
            "high" => high += 1,
            _ => unreachable!(),
        }
        println!("{sensor}:{band}");
    }
    println!("low={low},normal={normal},high={high}");
}

pub fn sensor_band(reading: i64, low: i64, high: i64) -> &'static str {
    if reading < low {
        "low"
    } else if reading > high {
        "high"
    } else {
        "normal"
    }
}

