source_texts.support_sla_repo:
mod sla;

use sla::due_minutes;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let priority = lines.next().unwrap_or("");
    let tier = lines.next().unwrap_or("");
    let after_hours = lines.next().unwrap_or("");
    println!("due_minutes={}|tier={tier}", due_minutes(priority, tier, after_hours));
}

pub fn due_minutes(priority: &str, tier: &str, after_hours: &str) -> i64 {
    let base = match priority {
        "high" => 120,
        "critical" => 30,
        _ => 480,
    };
    let adjusted = if tier == "premium" {
        (base - 30).max(15)
    } else {
        base
    };
    adjusted + if after_hours == "yes" { 60 } else { 0 }
}

source_texts.priority_digest_repo:
pub fn include_priority(priority: i64, minimum: i64) -> bool {
    priority >= minimum
}

pub fn format_message(index: usize, priority: i64, message: &str) -> String {
    format!("{index}|{priority}|{message}")
}

mod digest_rules;

use digest_rules::{format_message, include_priority};
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let minimum: i64 = lines.next().unwrap_or("0").parse().unwrap();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for offset in 0..count {
        let line = lines.next().unwrap_or("");
        let mut parts = line.splitn(2, '|');
        let priority: i64 = parts.next().unwrap().parse().unwrap();
        let message = parts.next().unwrap_or("");
        if include_priority(priority, minimum) {
            contents.push_str(&format_message(offset + 1, priority, message));
            contents.push('\n');
            saved += 1;
            characters += message.chars().count();
        }
    }
    fs::write("priority_digest.txt", contents).unwrap();
    println!("saved={saved}|skipped={}|characters={characters}", count - saved);
}

source_texts.inventory_reservation_repo:
pub fn available_stock(stock: i64, reserved: i64, mode: &str) -> i64 {
    if mode == "urgent" {
        stock
    } else {
        (stock - reserved).max(0)
    }
}

mod inventory;

use inventory::available_stock;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let stock: i64 = lines.next().unwrap().parse().unwrap();
    let demand: i64 = lines.next().unwrap().parse().unwrap();
    let reserved: i64 = lines.next().unwrap().parse().unwrap();
    let mode = lines.next().unwrap();
    let available = available_stock(stock, reserved, mode);
    let fulfilled = demand.min(available);
    let backorder = demand - fulfilled;
    let remaining = available - fulfilled;
    println!("fulfilled={fulfilled}|backorder={backorder}|remaining={remaining}");
}

