use report_rules::{format_entry, include_entry};
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let minimum_length: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for offset in 0..count {
        let entry = lines.next().unwrap_or("");
        if include_entry(entry, minimum_length) {
            contents.push_str(&format_entry(offset + 1, entry));
            contents.push('\n');
            saved += 1;
            characters += entry.chars().count();
        }
    }
    fs::write("filtered_report.txt", contents).unwrap();
    println!("saved={saved}|skipped={}|characters={characters}", count - saved);
}

pub fn format_entry(index: usize, entry: &str) -> String {
    format!("{index}|{entry}")
}

pub fn include_entry(entry: &str, minimum_length: usize) -> bool {
    entry.chars().count() >= minimum_length
}

