source_texts.score_band_repo:
from scores import score_band

pass_mark = int(input())
excellence_mark = int(input())
count = int(input())
counts = {"excellent": 0, "pass": 0, "retry": 0}
for _ in range(count):
    user, raw_score = input().split("|", 1)
    band = score_band(int(raw_score), pass_mark, excellence_mark)
    counts[band] += 1
    print(f"{user}:{band}")
print(
    f"excellent={counts['excellent']},pass={counts['pass']},retry={counts['retry']}"
)

def score_band(score: int, pass_mark: int, excellence_mark: int) -> str:
    if score >= excellence_mark:
        return "excellent"
    if score >= pass_mark:
        return "pass"
    return "retry"

