from sla import due_minutes

priority = input()
tier = input()
after_hours = input()
print(f"due_minutes={due_minutes(priority, tier, after_hours)}|tier={tier}")

def due_minutes(priority: str, tier: str, after_hours: str) -> int:
    if priority == "high":
        minutes = 120
    elif priority == "critical":
        minutes = 30
    else:
        minutes = 480
    if tier == "premium":
        minutes = max(minutes - 30, 15)
    if after_hours == "yes":
        minutes += 60
    return minutes

