mod path_rules;

use path_rules::sanitize_name;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut characters = 0;
    for _ in 0..count {
        let record = lines.next().unwrap_or("");
        let (owner, name) = record.split_once('|').unwrap();
        let slug = sanitize_name(name);
        characters += slug.chars().count();
        println!("{owner}:{slug}");
    }
    println!("entries={count},characters={characters}");
}

pub fn sanitize_name(name: &str) -> String {
    name.to_lowercase().replace(' ', "-")
}

