mod scores;

use scores::score_band;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let pass_mark: i64 = lines.next().unwrap().parse().unwrap();
    let excellence_mark: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut excellent, mut pass, mut retry) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let user = parts.next().unwrap();
        let score: i64 = parts.next().unwrap().parse().unwrap();
        let band = score_band(score, pass_mark, excellence_mark);
        match band {
            "excellent" => excellent += 1,
            "pass" => pass += 1,
            _ => retry += 1,
        }
        println!("{user}:{band}");
    }
    println!("excellent={excellent},pass={pass},retry={retry}");
}

pub fn score_band(score: i64, pass_mark: i64, excellence_mark: i64) -> &'static str {
    if score >= excellence_mark {
        "excellent"
    } else if score >= pass_mark {
        "pass"
    } else {
        "retry"
    }
}

