pub fn due_minutes(priority: &str, tier: &str, after_hours: bool) -> i64 {
    let base = match priority {
        "high" => 120,
        "critical" => 30,
        _ => 480,
    };
    let adjusted = if tier == "premium" {
        (base - 30).max(15)
    } else {
        base
    };
    adjusted + if after_hours { 60 } else { 0 }
}

