ledger_reconciliation_repo.source_text:
pub fn absolute_difference(expected: i64, actual: i64) -> i64 {
    (expected - actual).abs()
}

pub fn within_tolerance(expected: i64, actual: i64, tolerance: i64) -> bool {
    absolute_difference(expected, actual) <= tolerance
}

mod ledger;

use ledger::{absolute_difference, within_tolerance};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let tolerance: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut matched, mut unmatched, mut variance) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let expected: i64 = parts.next().unwrap().parse().unwrap();
        let actual: i64 = parts.next().unwrap().parse().unwrap();
        let difference = absolute_difference(expected, actual);
        variance += difference;
        if within_tolerance(expected, actual, tolerance) {
            matched += 1;
            println!("{id}:match");
        } else {
            unmatched += 1;
            println!("{id}:diff={difference}");
        }
    }
    println!("matched={matched},unmatched={unmatched},variance={variance}");
}

