use payroll::calculate_pay;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut total = 0;
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let employee = parts.next().unwrap();
        let hours: i64 = parts.next().unwrap().parse().unwrap();
        let rate: i64 = parts.next().unwrap().parse().unwrap();
        let pay = calculate_pay(hours, rate);
        total += pay;
        println!("{employee}:pay={pay}");
    }
    println!("total={total}");
}

pub fn calculate_pay(hours: i64, rate: i64) -> i64 {
    hours.min(40) * rate + (hours - 40).max(0) * rate * 2
}

